gold.schema_ddl:
CREATE TABLE citta (
    id SERIAL PRIMARY KEY,
    nome TEXT NOT NULL,
    provincia_id INT REFERENCES citta(id)
);

CREATE TABLE spedizioni (
    id SERIAL PRIMARY KEY,
    citta_origine_id INT NOT NULL REFERENCES citta(id),
    citta_destinazione_id INT NOT NULL REFERENCES citta(id),
    peso_kg NUMERIC(10,2) CHECK (peso_kg >= 0),
    data_spedizione DATE NOT NULL,
    stato TEXT CHECK (stato IN ('in_transito', 'consegnata', 'annullata'))
);
